exec salloc --partition=interactive_gpu --qos=class --account=en535743-ext-mrafiei1 --nodes=1 --ntasks=1 --cpus-per-task=10 --mem=32000M --gres=gpu:2g.40gb:1 --time=04:00:00 --comment=accept_cost --job-name=vscode \
  /bin/bash -c '
