    node="$(scontrol show hostnames "$SLURM_NODELIST" | head -1)"
    # Skipjack has no netcat, so we use the bash-native /dev/tcp to reach the
    # node sshd. On disconnect this exits and salloc releases the job.
    exec 3<>"/dev/tcp/${node}/22"
    cat <&3 &
    up=$!
    cat >&3
    kill "$up" 2>/dev/null || true
  '
